# ---------------------------------------------------------------- central incentives
ARTICLES.append(article(
    'data-centre-incentives-india-central',
    'Data centre incentives in India: infrastructure status, tax holiday and SEZs (2026)',
    'Central data centre incentives in India: infrastructure status for 5 MW+ IT load since October 2022, a tax holiday to 2047 for cloud services, FDI and SEZ rules.',
    'India',
    'Since 11 October 2022, an Indian data centre with a minimum capacity of 5 MW of IT load has had infrastructure status, and from tax year 2026-27 to tax year 2046-47 foreign companies that provide cloud services globally using data centre services procured in India are exempt from Indian tax on that income. The exemption comes from the Finance Act 2026; the Taxation and Other Laws (Amendment) Act 2026, which received assent on 17 August 2026, eased its conditions. Law firms read the FDI policy as allowing 100% foreign investment under the automatic route for companies engaged only in the data centre business.',
    [
        'Infrastructure status, notified on 11 October 2022, needs a dedicated or centralised building and a minimum capacity of 5 MW of IT load.',
        'The tax holiday benefits the foreign cloud company; profits of the Indian data centre company and the reseller remain taxable, according to the government backgrounder.',
        'The Taxation and Other Laws (Amendment) Act 2026, which received assent on 17 August 2026, drops the notification and approved-scheme conditions and extends the holiday to data centres leased and operated by an Indian company.',
        'The SEZ land relaxations in effect from 3 June 2025 cover semiconductor and electronic component manufacturing; data centres are not among the listed sectors.',
    ],
    [
        sec('summary', 'Central data centre incentives in India at a glance',
            table(['Incentive', 'What it gives', 'Who qualifies', 'Status'], [
                ['Infrastructure status', 'Easier access to institutional credit at lower rates (PTI report)', 'Data centre in a dedicated or centralised building, minimum 5 MW of IT load', 'Notified 11 October 2022'],
                ['Tax holiday', 'Exemption on a foreign company’s income from data centre services procured in India', 'Foreign cloud company that does not own or operate the facility and sells to Indian users through an Indian reseller', 'Tax years 2026-27 to 2046-47'],
                ['Safe harbour', '15% margin on cost where the Indian data centre provider is a related entity', 'Related-party data centre services', 'Proposed in Budget 2026-27'],
                ['Foreign investment', '100% under the automatic route', 'Companies engaged only in the data centre business; investors from listed restricted countries such as China need prior approval', 'Law-firm reading of the FDI policy'],
                ['SEZ land relaxation', 'Minimum land requirement cut from 50 hectares to 10 hectares', 'Semiconductor and electronic component manufacturing units', 'Data centres not among the listed sectors'],
            ], 'hml', 'tribune-hml', 'pib-budget', 'snr', 'khaitan', 'sez-bs'),
        ),
        sec('infrastructure-status', 'Infrastructure status for data centres under the Harmonised Master List',
            p('The Ministry of Finance added data centres to the Harmonised Master List of Infrastructure Sub-sectors, under Communication, by a notification dated 11 October 2022. The entry covers a "Data Centre housed in a dedicated/centralized building for storage and processing of digital data applications with a minimum capacity of 5 MW of IT load."', 'hml'),
            p('According to a PTI report at the time, the move helps data centre companies get easier access to institutional credit at lower rates and attract foreign investment.', 'tribune-hml'),
        ),
        sec('tax-holiday', 'The tax holiday to 2047 for cloud services delivered from India',
            p('The Budget of 1 February 2026 proposed a tax holiday till 2047 for foreign companies providing cloud services to customers globally using data centre services from India, with services to Indian customers provided through an Indian reseller entity. It also proposed a safe harbour of 15% on cost where the Indian data centre service provider is a related entity. Electronics and IT Minister Ashwini Vaishnaw said investments of around USD 70 billion were underway and around USD 90 billion had been announced.', 'pib-budget'),
            p('The government backgrounder sets the window at tax year 2026-27 to tax year 2046-47 and says profits from domestic activity, including data centre services provided by the resident Indian data centre company and resale by the Indian reseller, remain taxable.', 'pib-backgrounder'),
            p('The Finance Act 2026, notified on 30 March 2026, exempts a foreign company’s income "by way of procuring data centre services from a specified data centre", if the foreign company is notified by the central government, does not own or operate the physical infrastructure or resources of the data centre, sells to users in India only through an Indian reseller company and furnishes prescribed information. A specified data centre had to be set up under an approved scheme, notified by MeitY, and owned and operated by an Indian company.', 'snr'),
            p('The Taxation and Other Laws (Amendment) Bill, 2026 passed the Lok Sabha on 6 August and the Rajya Sabha on 10 August 2026, and received the President’s assent on 17 August 2026. It removes the conditions that the foreign company be notified and that the data centre be set up under an approved scheme and notified, and extends the exemption to data centres leased and operated by an Indian company. Check any rules or schemes issued under it before relying on the amended conditions.', 'prs', 'ob-assent'),
        ),
        sec('fdi', 'Foreign investment (FDI) rules for data centres',
            p('Khaitan & Co reads India’s FDI policy as allowing 100% foreign investment under the automatic route in Indian companies or LLPs engaged only in the data centre business. If the company is also in other businesses, for example owning fibre assets, the investment conditions for those sectors apply as well. S&R Associates notes that investors from restricted countries (Pakistan, Afghanistan, Nepal, Bhutan, China including Hong Kong, Bangladesh and Myanmar) need prior government approval.', 'khaitan', 'snr'),
        ),
        sec('sez-gift', 'SEZ rules, GIFT City and data embassies',
            p('The SEZ (Amendment) Rules 2025, in effect from 3 June 2025, cut the minimum land requirement for semiconductor and electronic component manufacturing units in SEZs from 50 hectares to 10 hectares. The sectors listed, such as semiconductors, printed circuit boards, lithium-ion cells and IT hardware components, do not include data centres.', 'sez-bs'),
            p('In the Budget 2023-24 speech the Finance Minister said that, for countries looking for digital continuity solutions, the government would facilitate data embassies in GIFT IFSC. DD India reports that Gujarat’s 2026 data centre policy document highlights Dholera and GIFT City among the state’s industrial hubs.', 'inc42-embassy', 'gj-dd'),
            links('State incentives', [(PAGES['data-centre-policy-india-state-comparison'], 'data-centre-policy-india-state-comparison'), (PAGES['gujarat-data-centre-policy'], 'gujarat-data-centre-policy'), (PAGES['uttar-pradesh-data-centre-policy'], 'uttar-pradesh-data-centre-policy'), (PAGES['maharashtra-data-centre-policy'], 'maharashtra-data-centre-policy')]),
            invariant('India'),
        ),
    ],
    [
        faq('Do data centres have infrastructure status in India?', 'Yes, since 11 October 2022, if the data centre is housed in a dedicated or centralised building and has a minimum capacity of 5 MW of IT load.', 'hml'),
        faq('What is the data centre tax holiday till 2047?', 'The tax holiday is an exemption, from tax year 2026-27 to tax year 2046-47, for foreign companies that provide cloud services globally using data centre services procured in India. Indian customers must be served through an Indian reseller.', 'pib-backgrounder', 'snr'),
        faq('Does the tax holiday cover an Indian data centre operator’s profits?', 'No. The government backgrounder says profits of the resident Indian data centre company and the Indian reseller remain taxable as for any other domestic company.', 'pib-backgrounder'),
        faq('What changed in the August 2026 amendment to the data centre tax holiday?', 'The amendment removes the notification and approved-scheme conditions and extends the exemption to data centres leased and operated, not only owned and operated, by an Indian company. The Taxation and Other Laws (Amendment) Act 2026 received assent on 17 August 2026.', 'prs', 'ob-assent'),
        faq('Is 100% FDI allowed in data centres in India?', 'Law firms read the FDI policy as allowing 100% foreign investment under the automatic route for companies engaged only in the data centre business. Investors from listed restricted countries such as China need prior government approval.', 'khaitan', 'snr'),
        faq('Do the 2025 SEZ land relaxations apply to data centres?', 'No. The SEZ (Amendment) Rules 2025 cut the minimum land requirement from 50 hectares to 10 hectares for semiconductor and electronic component manufacturing units, and data centres are not among the listed sectors.', 'sez-bs'),
    ],
    srcs('hml', 'tribune-hml', 'pib-budget', 'pib-backgrounder', 'snr', 'prs', 'ob-assent', 'khaitan', 'sez-bs', 'inc42-embassy', 'gj-dd'),
    ['national-data-centre-policy-india', 'data-centre-policy-india-state-comparison', 'dpdp-data-localisation-data-centres-india', 'data-centre-investment-india', 'data-centres-in-india'],
    minutes=7,
))

# ---------------------------------------------------------------- DPDP and localisation
ARTICLES.append(article(
    'dpdp-data-localisation-data-centres-india',
    'DPDP Act and data localisation: what it means for data centres in India (2026)',
    "India's DPDP Act 2023 does not require blanket data localisation, but RBI, SEBI, IRDAI, CERT-In and telecom rules do. What each rule means for data centres.",
    'India',
    'India’s Digital Personal Data Protection (DPDP) Act 2023 does not require all personal data to stay in India: under Section 16, the central government can restrict transfers to countries it notifies, and stricter laws on transfer stay in force. The DPDP Rules 2025, notified in November 2025 with an 18-month phased timeline, let the government require significant data fiduciaries to keep specified personal data in India; according to Taxmann, that rule and Section 16 apply from 13 May 2027. Sector rules already require localisation: RBI for payment system data since 2018, SEBI for regulated entities’ cloud data since 2023, IRDAI for insurance-sector logs and data, and CERT-In for logs.',
    [
        'DPDP Act Section 16 works as a negative list: transfers abroad are allowed unless the central government notifies a country as restricted.',
        'Section 16 and the Rules on significant data fiduciaries and cross-border transfer apply from 13 May 2027, according to Taxmann.',
        'RBI’s circular of 6 April 2018 requires the entire payment system data to be stored only in India.',
        'SEBI’s cloud framework of 6 March 2023 requires regulated entities to keep cloud data, including DR and logs, within India.',
        'CERT-In’s directions of 28 April 2022 require ICT logs to be kept within India for a rolling 180 days, and data centres to keep validated subscriber records for 5 years or longer.',
    ],
    [
        sec('rules-table', 'Data localisation rules in India at a glance',
            table(['Rule', 'Who it binds', 'What must stay in India', 'Since'], [
                ['RBI circular of 6 April 2018', 'Payment system providers', 'The entire data relating to payment systems, including end-to-end transaction details', 'Compliance reported by 15 October 2018'],
                ['SEBI cloud framework of 6 March 2023', 'SEBI regulated entities', 'Data and processing, including DC, DR, near-DR and logs; PaaS and SaaS only in MeitY-empanelled data centres with a valid STQC audit status', '2023'],
                ['IRDAI Information and Cyber Security Guidelines, 24 April 2023', 'Insurance-sector regulated entities', 'All ICT infrastructure logs, critical and business data (entities other than insurers); insurers under separate record-keeping rules', '2023, amended 6 April 2026'],
                ['CERT-In directions of 28 April 2022', 'Service providers, intermediaries, data centres, body corporates and government organisations', 'ICT logs for a rolling 180 days within Indian jurisdiction', '2022'],
                ['Unified Licence clause 39.23(viii)', 'Telecom licensees', 'Subscriber accounting information and user information, with listed exceptions', 'Licence condition'],
                ['DPDP Act Section 16', 'All data fiduciaries', 'Nothing by default; transfers to notified countries can be restricted', 'Act of 11 August 2023; section applies from 13 May 2027'],
                ['DPDP Rules 2025', 'Significant data fiduciaries', 'Personal data the government specifies on a committee’s recommendation, with its traffic data', 'From 13 May 2027'],
            ], 'rbi', 'sebi', 'irdai-cam', 'irdai-2026', 'certin', 'dot-ul', 'dpdp-act', 'taxmann-loc'),
        ),
        sec('dpdp-act', 'DPDP Act rules on cross-border data transfer',
            p('Section 16(1) of the DPDP Act says the central government "may, by notification, restrict the transfer of personal data by a Data Fiduciary for processing to such country or territory outside India as may be so notified." Section 16(2) keeps any other law that provides "a higher degree of protection for or restriction on transfer", so sector rules such as RBI’s continue to apply on their own terms.', 'dpdp-act', 'taxmann-loc'),
            p('Section 10 of the DPDP Act lets the government notify significant data fiduciaries on factors including the volume and sensitivity of data, risk to the rights of data principals, sovereignty and integrity of India, electoral democracy, security of the State and public order. They must appoint a Data Protection Officer based in India and an independent data auditor, and carry out periodic data protection impact assessments and audits. The highest penalty in the Schedule, up to ₹250 crore, is for failing to take reasonable security safeguards to prevent a personal data breach.', 'dpdp-act'),
        ),
        sec('dpdp-rules', 'DPDP Rules 2025 and the May 2027 compliance date',
            p('PIB announced on 14 November 2025 that the government had notified the DPDP Rules 2025 with an 18-month phased compliance timeline. Consent managers must be Indian companies, data fiduciaries must respond to data principal requests within a maximum of 90 days, and significant data fiduciaries "must also comply with government-specified restrictions on certain categories of data, including localisation where required."', 'pib-dpdp'),
            p('Under the Rules, a significant data fiduciary must ensure that personal data specified by the central government, on the recommendation of a committee, and the traffic data relating to its flow are not transferred outside India. Taxmann, in an analysis updated on 15 November 2026, gives 13 May 2027 as the date from which this rule and Section 16 apply.', 'taxmann-loc'),
            p('In January 2026 Business Standard reported that MeitY had proposed cutting the implementation period for certain provisions for significant data fiduciaries from 18 to 12 months.', 'bs-dpdp'),
        ),
        sec('sector-rules', 'RBI, SEBI, IRDAI, CERT-In and telecom rules that already require data in India',
            p('RBI’s circular of 6 April 2018 requires all system providers to ensure that "the entire data relating to payment systems operated by them are stored in a system only in India", including full end-to-end transaction details. The foreign leg of a transaction may also be stored abroad.', 'rbi'),
            p('SEBI’s cloud framework of 6 March 2023 says "the data should reside/be processed within the legal boundaries of India", covering DC, DR, near-DR and logs. For PaaS and SaaS, regulated entities may only choose providers that host and process their data within data centres empanelled by MeitY and holding a valid STQC audit status.', 'sebi'),
            p('IRDAI’s guidelines of 24 April 2023 require regulated entities other than insurers to store all ICT infrastructure logs, critical and business data in India. Insurers must store primary data in India under separate guidelines and regulations. IRDAI issued amendments to the guidelines on 6 April 2026; confirm whether the localisation clause changed.', 'irdai-cam', 'irdai-2026'),
            p('CERT-In’s directions of 28 April 2022 require cyber incidents to be reported within 6 hours and ICT logs to be kept for a rolling 180 days within Indian jurisdiction. Data centres, VPS, cloud and VPN providers must also keep validated subscriber records for 5 years or longer.', 'certin'),
            p('Telecom licensees may not transfer subscriber accounting information or user information outside India, with exceptions for international roaming, billing and IPLC subscribers, under clause 39.23(viii) of the Department of Telecommunications’ Unified Licence.', 'dot-ul'),
        ),
        sec('meaning', 'What data localisation rules mean for data centre demand and design',
            ul([
                'Payment system providers, SEBI regulated entities and insurance-sector regulated entities must keep defined data in India; for SEBI regulated entities this includes DR and near-DR copies.',
                'Operators that want SEBI-regulated PaaS and SaaS workloads need MeitY empanelment and a valid STQC audit status for the facility.',
                'CERT-In names data centres directly: log retention, incident reporting and subscriber records are duties of the facility, not only of its tenants.',
                'The DPDP Act alone does not force localisation today. Watch for significant data fiduciary notifications and any restricted-country list.',
            ], 'rbi', 'sebi', 'irdai-cam', 'certin', 'dpdp-act'),
            p('This page summarises public rules and is not legal advice.'),
            invariant('India'),
        ),
    ],
    [
        faq('Does the DPDP Act require data localisation in India?', 'Not by default: Section 16 of the DPDP Act allows transfers abroad unless the government notifies a country as restricted. It also keeps stricter laws, such as RBI’s payment data rule, in force.', 'dpdp-act', 'taxmann-loc'),
        faq('When do the DPDP Rules 2025 come into force?', 'In phases over 18 months from their notification in November 2025. According to Taxmann, Section 16 and the Rules on significant data fiduciaries and cross-border transfer apply from 13 May 2027.', 'pib-dpdp', 'taxmann-loc'),
        faq('Do payment companies have to store data in India?', 'Yes. Under RBI’s circular of 6 April 2018, the entire data relating to payment systems must be stored only in India.', 'rbi'),
        faq('Can SEBI regulated entities use cloud data centres outside India?', 'No. SEBI’s 2023 cloud framework requires the data, including DR and logs, to reside and be processed within India.', 'sebi'),
        faq('What does CERT-In require from a data centre in India?', 'CERT-In’s 2022 directions require incident reports within 6 hours, ICT logs kept within India for 180 days, and validated subscriber records kept for 5 years or longer.', 'certin'),
        faq('Does a data centre need MeitY empanelment?', 'Yes, to host PaaS and SaaS workloads for SEBI regulated entities: those providers must host and process the data only in data centres empanelled by MeitY and holding a valid STQC audit status.', 'sebi'),
    ],
    srcs('rbi', 'sebi', 'irdai-cam', 'irdai-2026', 'certin', 'dot-ul', 'dpdp-act', 'pib-dpdp', 'taxmann-loc', 'bs-dpdp'),
    ['national-data-centre-policy-india', 'data-centre-incentives-india-central', 'data-centre-approvals-india', 'data-centre-companies-india', 'data-centres-in-india'],
    minutes=8,
))

